insert into mach_channels (machine_key, org, lane, kind, country, city, role, brands, site, email, phone, stock, note, source, confidence, verdict) values
  ('R1700G', 'Borusan Makina Kazakhstan LLP (BMGS Kazakhstan, Borusan Cat Казахстан)', 'dealers', 'дилер', 'KZ', 'Алматы', 'официальный дилер Caterpillar в Казахстане с июля 1999 г.; полная линейка Cat, включая подземную горную технику', 'Caterpillar, SEM, FG Wilson', 'https://www.borusancat.kz/', 'info-bmk@borusan.com', '8 800 0800 228', '14 точек в РК (Алматы, Астана, Караганда, Актау, Актобе, Шымкент, Сатпаев, Усть-Каменогорск, Костанай, Атырау, Уральск, Кокшетау); склад запчастей и цех ремонта; официальных поставок в РФ не делает', 'ближайший к РФ официальный канал по R1700G: на сайте дилера есть карточка машины https://www.borusancat.kz/en/equipment/new/13866077/Underground-Hard-Rock/18233686/R1700G . По подземному проекту Anglo Asian (Азербайджан) крупные узлы Cat держат на региональных складах Борусан в Турции и Казахстане — значит по R1700 позиции в регионе реально есть. Контакты и 14 адресов вытянуты из JSON карты локаций на собственном сайте Borusan Cat.', 'https://www.borusancat.com/en/contact/map', 'high', null),
  ('R1700G', 'Borusan Cat Kyrgyzstan (BMGS Kyrgyzstan)', 'dealers', 'дилер', 'KG', 'Бишкек', 'официальный дилер Caterpillar в Кыргызстане с 2003 г.; горная и дорожная техника, оригинальные запчасти и масла', 'Caterpillar, SEM, FG Wilson', 'https://www.borusancat.kg/', 'info-bmkg@borusan.com', '+996 228 858 858', '3 точки: Бишкек, Балыкчы, Ош; глубокий склад — у головного дилера в Алматы/Турции', 'в каталоге есть R1700 (https://www.borusancat.kg/en/equipment/new/13866077/underground-hard-rock/730743084457382/r1700). Полезен как альтернативный ЕАЭС-адрес: КР в ЕАЭС, значит ввоз из КР в РФ без таможенной границы.', 'https://www.borusancat.com/en/contact/map', 'high', null),
  ('R1700G', 'Borusan Makina ve Güç Sistemleri Azerbaijan (BMGS Azerbaijan)', 'dealers', 'дилер', 'AZ', 'Баку', 'официальный дилер Caterpillar в Азербайджане с 1997 г.; первый в стране парк подземной техники Cat', 'Caterpillar, SEM, FG Wilson', 'https://www.borusancat.az/', 'infoaz@borusancat.com', '+994 12 377 02 28', 'склад запчастей и расходников в Азербайджане (Баку-Шихово, Salyan Highway 15 km); крупные узлы — на региональных складах в Турции и Казахстане', 'в декабре 2023 г. Anglo Asian Mining получила на Гедабек 3 подземных погрузчика Cat R1700 (15 т) и 2 Cat 980UMA — первая подземная техника Cat в Азербайджане; сервис и запчасти по контракту ведёт Борусан. Это единственный известный парк R1700 у ближайших соседей РФ с формализованной запчастной поддержкой.', 'https://im-mining.com/2023/12/12/caterpillar-borusan-make-historic-underground-equipment-delivery-to-anglo-asian-mining-in-azerbaijan/', 'high', null),
  ('R1700G', 'Borusan Makina ve Güç Sistemleri Georgia (BMGS Georgia)', 'dealers', 'дилер', 'GE', 'Тбилиси (филиал Терджола)', 'официальный дилер Caterpillar в Грузии с 1997 г.', 'Caterpillar, SEM, FG Wilson', 'https://www.borusancat.ge/', 'info-ge@borusancat.com', '+995 32 2 222 522', '2 точки: головной офис Тбилиси (Kakheti Highway 118) и филиал Терджола', 'Грузия — один из трёх-четырёх транзитных маршрутов оригинала в РФ; сам дилер в РФ не поставляет, но служит источником для реэкспортёров.', 'https://www.borusancat.com/en/contact/map', 'high', null),
  ('R1700G', 'Borusan Makina ve Güç Sistemleri A.Ş. (Borusan Cat Türkiye)', 'dealers', 'дилер', 'TR', 'Истанбул', 'официальный дилер Caterpillar в Турции с 1994 г.; головная компания группы дилеров Борусан (TR, AZ, GE, KZ, KG)', 'Caterpillar, SEM, FG Wilson, Faresin', 'https://www.borusancat.com/', 'info-cat@borusan.com', '+90 216 507 17 15', '40 точек в Турции (клиентские центры и ревизионные центры: Адана, Анкара, Анталья, Бурса, Диярбакыр, Испарта, Измир, Трабзон и др.); региональный склад крупных узлов Cat для Кавказа и Центральной Азии', 'принимает заказы запчастей через Parts.Cat.Com (собственная страница «Yedek Parça → Parça Mağazası (Parts.Cat.Com)»). Держит подземную линейку в каталоге (R1700). Турция — главный хаб пересборки цепочки на РФ после 2022 г.', 'https://www.borusancat.com/tr/part', 'high', null),
  ('R1700G', 'ИП ООО «Zeppelin Central Asia Machinery»', 'dealers', 'дилер', 'UZ', 'Ташкент', 'официальный дилер Caterpillar в Узбекистане (около 20 лет), часть Zeppelin GmbH — крупнейшего дилера Cat в Европе', 'Caterpillar, SEM', 'https://www.zeppelin.uz/', 'zub-centralasia@zeppelin.com', '+998 78 150 99 33', '4 точки: Ташкент (Сергели, Кольцевая, Ханабад), Наманган, Карши, Зарафшан; сервис 24/7', 'точка в Зарафшане — это промзона НГМК (Навоийский ГМК), то есть дилер уже работает по подземной и карьерной добыче. Раздел «Горная и карьерная техника» и «Сервис и запчасти» на сайте. Узбекистан не в ЕАЭС — ввоз в РФ через таможню.', 'https://www.zeppelin.uz/contacts', 'high', null),
  ('R1700G', 'Zeppelin Tajikistan', 'dealers', 'дилер', 'TJ', 'Душанбе', 'официальный дилер техники и энергетического оборудования Cat в Таджикистане', 'Caterpillar', 'https://www.zeppelin.tj/', 'info@zeppelin.tj', '+992 44 625 11 22', 'Душанбе, пр. Негмата Карабаева 200; глубина склада не заявлена', 'в каталоге есть раздел «Горная и карьерная техника» и «Сервис и запчасти»; поставлено более 300 машин Cat. Слабое звено по объёму, но формально официальный канал.', 'https://www.zeppelin.tj/brands/cat/', 'high', null),
  ('R1700G', 'ООО «Zeppelin Armenia»', 'dealers', 'дилер', 'AM', 'Абовян (Ереван)', 'официальный дилер Cat в Республике Армения (около 20 лет), часть Zeppelin GmbH', 'Caterpillar', 'https://www.zeppelin.am/', null, '+374 60 52 00 00', '4 подразделения, 3 сервисных центра (в т.ч. Каджаран и Техут — действующие рудники), 157 сотрудников', 'на собственном сайте прямо заявлен статус официального дилера Cat в Армении. Есть российский номер +7 800 100 14 51 на сайте — признак работы с российскими клиентами. Армения в ЕАЭС: ввоз в РФ без таможенной границы. Корпоративная почта на сайте не опубликована, только форма.', 'https://www.zeppelin.am/eng/', 'high', null),
  ('R1700G', 'Barloworld Mongolia LLC (ранее Wagner Asia Equipment LLC)', 'dealers', 'дилер', 'MN', 'Улан-Батор', 'официальный дилер Caterpillar в Монголии (дилерство с 1996 г., в 2021 г. выкуплено Barloworld)', 'Caterpillar, SEM, Michelin', 'https://www.barloworld.mn/', null, '7018 7588', 'сеть сервисных баз по Монголии; сильная горная компетенция (Оюу-Толгой, Таван-Толгой)', 'статус дилера подтверждён на собственном сайте Caterpillar (catused.cat.com — карточка дилера BARLOWORLD MONGOLIA LLC). Тот же владелец, что у российской «Восточной Техники», — практический мостик по оригиналу через Монголию. Корпоративной почты на сайте нет, только форма.', 'https://catused.cat.com/en/dealer.aspx?orgid=%7B42e2f3fa-97f8-46f0-916c-673c0c9b2063%7D', 'high', null),
  ('R1700G', 'Mohamed Abdulrahman Al-Bahar LLC', 'dealers', 'дилер', 'AE', 'Шарджа (головной офис)', 'официальный дилер Caterpillar по ОАЭ, Кувейту, Катару, Оману и Бахрейну; горное направление в наличии', 'Caterpillar, Cat Power Systems', 'https://www.albahar.com/', 'webinfo@albahar.com', '+971 6 543 3555', 'Шарджа (159 Al-Wasit Street, Ind. Area 3), Абу-Даби (Mussafah, Plot 36 Sector M-15), Дубай (склад запчастей, +971 4 266 0255), Джебель-Али; дежурная служба запчастей вне рабочих часов', 'крупнейший официальный источник оригинала в ОАЭ. Сам в РФ не поставляет, но именно вокруг него живёт дубайский слой реэкспортёров, через который оригинал доходит до РФ.', 'https://www.albahar.com/contact-us/locate-us/uae/', 'high', null),
  ('R1700G', 'Lei Shing Hong Machinery Ltd (LSHM)', 'dealers', 'дилер', 'CN', 'Куньшань (Цзянсу), группа — Гонконг', 'первый дилер Caterpillar в материковом Китае (с 1994 г.); территория — Шанхай, Цзянсу, Чжэцзян, Шаньдун, Хэнань, Аньхой, Хубэй', 'Caterpillar, Perkins', 'https://www.lsh.com/machinery/', 'info@lsh.com', '+86 512 5766 3168', 'сеть филиалов по востоку Китая, собственный Equipment Rebuild Center (капремонт узлов) и склад запчастей', 'Китай — фактический главный источник оригинала для РФ (по нашей таможне 2023 г. ровно 20 из 35 строк Cat шли от CATERPILLAR (QINGZHOU) CO. LTD, КНР). LSHM — легальный вход в китайскую дилерскую систему Cat. Контакты с корпоративного сайта группы LSH.', 'https://www.lsh.com/machinery/', 'high', null),
  ('R1700G', 'Lei Shing Hong Machinery North China (ранее WesTrac China)', 'dealers', 'дилер', 'CN', 'Пекин', 'региональный дилер Caterpillar по северу и северо-востоку Китая: Хэйлунцзян, Цзилинь, Ляонин, Шаньси, Хэбэй, Внутренняя Монголия, Пекин, Тяньцзинь', 'Caterpillar', 'https://www.lsh.com/machinery/', 'info@lsh.com', '+86 10 5902 1666', 'сеть по северным провинциям; горная специализация (наследие WesTrac China от Seven Group)', 'в 2017 г. Seven Group Holdings продала китайское горное дилерство (WesTrac China) группе Lei Shing Hong за 428 млн долл.; территория граничит с РФ и Монголией — практически удобная точка входа. Телефон пекинского офиса — из контактов корпоративного сайта LSH.', 'https://www.miningglobal.com/automation-and-ai/seven-group-holdings-sells-chinese-mining-machinery-arm-lei-shing-hong-dollar428mn', 'med', null),
  ('R1700G', 'China Engineers Limited (CEL), группа Sime Darby', 'dealers', 'дилер', 'CN', 'Фошань (Гуандун)', 'единственный дистрибьютор Cat в семи провинциях КНР: Гуандун, Гуанси, Хайнань, Фуцзянь, Цзянси, Хунань и Синьцзян', 'Caterpillar', 'http://cel-cat.com.cn', 'cel@simedarby.com.hk', '+86 757 2239 8880', '57 200 наименований на складе, не менее 85 % позиций — со склада; система складского учёта подключена к глобальной сети поставок запчастей Caterpillar', 'важнейшая деталь: в территорию CEL входит Синьцзян — то есть официальный дилерский склад Cat стоит вплотную к Казахстану, на сухопутном коридоре в ЕАЭС. Для закупки под R1700G это самый короткий официальный путь «оригинал → ЕАЭС → РФ».', 'https://www.simeindustrial.com/caterpillar-dealership/china-engineers-limited', 'high', null),
  ('R1700G', 'Gmmco Limited (CK Birla Group)', 'dealers', 'дилер', 'IN', 'Ченнаи', 'крупнейший дилер Caterpillar в Индии (с 1967 г.); юг, центр и запад Индии; горное направление выделено отдельно', 'Caterpillar, Cat Power Systems', 'https://www.gmmco.in/', 'sales@gmmcoindia.com', '1800 425 2546', 'более 100 филиалов, цеха капремонта (Бутибори/Нагпур, Ченнаи); онлайн-заказ Cat-запчастей, SIS 2.0, Cat Central, Cat Integrated Procurement', 'Индия — недооценённый канал: у Gmmco полноценный доступ к parts.cat.com и SIS 2.0, крупный склад и ремонтная база. Расчёты в рупиях, логистика в РФ — море/Иран или авиа.', 'https://www.gmmco.in/contact-us', 'high', null),
  ('R1700G', 'Gainwell Commosales Pvt Ltd (ранее Tractors India Pvt Ltd, TIPL)', 'dealers', 'дилер', 'IN', 'Колката', 'авторизованный дилер Cat по северу и востоку Индии и Бутану; сестринская Gainwell Engineering по лицензии Caterpillar делает подземную технику room-and-pillar и поставляет к ней запчасти', 'Caterpillar', 'https://www.gainwellindia.com/', null, null, 'более 80 филиалов, площадок и цехов; завод подземной техники на 35 акрах в Панагархе (Западная Бенгалия)', 'единственный в регионе дилер Cat с собственным производством подземной горной техники и обязательством поставлять aftermarket-запчасти к лицензированной подземной технике Cat. По ПДМ R1700G прямого мандата нет (лицензия — на room-and-pillar), но компетенция по подземке есть. Контактов на уровне корпоративной почты в открытом виде не нашёл.', 'https://northamericanmining.com/index.php/2022/04/19/gainwell-engineering-caterpillar-sign-underground-tech-deal/', 'med', null),
  ('R1700G', 'Eltrak S.A. (ELTRAK Group)', 'dealers', 'дилер', 'GR', 'Афины (Неа-Кифисия)', 'официальный дилер Caterpillar в Греции (с 1982 г.) и Болгарии; по линии судовых двигателей MaK территория Cat включает KZ, KG, TJ, TM, UZ, AM, AZ, GE, MD, MN, UA', 'Caterpillar, MaK', 'https://eltrak.gr/en/', null, '+30 210 8196800', 'склады в Греции и Болгарии', 'ВАЖНАЯ ОГОВОРКА: широкая центральноазиатская территория Eltrak в официальном локаторе Cat относится к судовым двигателям MaK, а не к землеройной и горной технике Cat — по машинам в этих странах дилеры Borusan и Zeppelin. Для R1700G Eltrak не канал; строку держим, чтобы никто не перепутал территории.', 'https://www.cat.com/en_US/by-industry/marine/mak-dealer-locator.html', 'med', null),
  ('R1700G', 'ООО «Восточная Техника» (ВТ), группа Barloworld', 'dealers', 'торговец', 'RU', 'Новосибирск', 'официальный дилер Caterpillar в РФ с 1998 г. по Сибири, Якутии и северу Дальнего Востока; сегодня на собственном сайте называет себя только «поставщик техники Cat, SEM»', 'Caterpillar, SEM, Weichai, DATC', 'https://www.vost-tech.ru/', 'info@vost-tech.ru', '8 800 250 70 60', '17 подразделений от Западной Сибири до Дальнего Востока, 17 складов запчастей, 7 сервисных центров; восстановленные и б/у запчасти отдельным разделом', 'ключевой факт для нас: ВТ реально ввозит оригинал — в нашей таможенной выборке 2023 г. ООО «Восточная Техника» стоит импортёром запчастей Cat из Германии и США. По открытым данным выручка 2023 г. > 20 млрд руб., за I кв. 2024 г. ввезено оборудования и запчастей Cat более чем на 24 млн долл. В марте 2025 г. закрыла малые подразделения (Алдан, Мирный, Москва, Нерюнгри, Петропавловск-Камчатский, Удачный, Улан-Удэ, Якутск). Barloworld подавал добровольное раскрытие в BIS (сентябрь 2024), итоговый отчёт — 1 сентября 2025 г., нарушений санкций США расследование не нашло. Слово «официальный дилер» с главной страницы сайта убрано — это надо учитывать в переписке.', 'https://www.vost-tech.ru/', 'high', null),
  ('R1700G', 'ООО «Мантрак Восток» (Mantrac Group, Mansour)', 'dealers', 'торговец', 'RU', 'Бор, Нижегородская обл.', 'был официальным дилером Caterpillar в РФ с 2000 г. по европейской части (Воркута, Гай, Екатеринбург, Казань, Москва, Пермь, Сургут, Тюмень, Уфа, Ухта, Челябинск)', 'Caterpillar, Bucyrus, SEM', null, null, null, 'нет: канал не работает', 'проверено вручную 12.09.2026: домен mantracvostok.ru отдаёт не сайт компании, а страницу-редирект на партнёрскую ссылку aviasales (`window.location = http://www.aviasales.ru/?marker=...mantracvostok_ru`), то есть домен отпущен/перепродан. HTTPS на нём не поднят. Mantrac Group публично сообщала о существенном сворачивании российской дочерней структуры. В РФ как канал по R1700G не рассматривать.', 'http://mantracvostok.ru/', 'high', null),
  ('R1700G', 'ООО «Цеппелин Русланд» (Zeppelin Russland)', 'dealers', 'торговец', 'RU', 'Москва', 'был официальным дилером Caterpillar по Центральному, Северо-Западному, части Приволжского и Южного ФО; сегодня — «официальный дилер сельхозтехники мировых производителей»', 'Agrifac, Agromaster, Nardi, KIVI-PEKKA, SEPPI, Western (Caterpillar в ассортименте нет)', 'https://www.zeppelin.ru/', 'zrs-help@zeppelin.ru', '+7 495 130 35 35', '7 филиалов в РФ, 9 брендов — все сельхоз; запчастей Cat не продаёт', 'проверено вручную: на главной странице zeppelin.ru слово Caterpillar не встречается ни разу, а карточка https://www.zeppelin.ru/products/arkhiv/brand-cat/r1700g/ помечена «АРХИВНАЯ МОДЕЛЬ… В настоящее время эта модель не доступна для продажи». Это самый чистый документальный след того, что немецкий канал Cat в РФ закрыт и заменён сельхозбизнесом. Потеря российского рынка стоила Zeppelin GmbH 16 % выручки в 2022 г.', 'https://www.zeppelin.ru/products/arkhiv/brand-cat/r1700g/', 'high', null),
  ('R1700G', 'ООО «Амур Машинери» / «Сахалин Машинери»', 'dealers', 'дилер', 'RU', 'Хабаровск', 'официальный дилер Caterpillar по Дальнему Востоку (более 25 лет); представительства Благовещенск, Тында, Находка, Южно-Сахалинск, Комсомольск', 'Caterpillar', 'https://amurmachinery.ru/', null, null, '8 складов запчастей, более 10 000 наименований; сервисные центры в Хабаровске и Благовещенске с высшей оценкой Cat «5 звёзд»', 'в справочнике дилеров Cat по РФ (обновление 01.12.2023) присутствует наравне с ВТ, Мантрак Восток и Цеппелин Русланд. В нашей таможенной выборке по ПДМ есть импортёр АО «Техсервис-Благовещенск» — тот же регион, тот же коридор через Хэйхэ. Собственный сайт из нашей среды не открывается (DNS/TLS), поэтому текущий статус на 2026 г. по первичному источнику не подтверждён — проверять до сделки.', 'https://exkavator.ru/dealers/producer/caterpillar', 'med', null),
  ('R1700G', 'Caterpillar Inc.', 'dealers', 'производитель-неоригинал', 'US', 'Ирвинг / Пеория', 'изготовитель; официального канала в РФ нет', 'Caterpillar, SEM, Cat Reman', 'https://www.caterpillar.com/', null, null, 'в РФ — нет', 'ОГОВОРКА ПО ПОЛЮ kind: в разрешённом перечне значений нет «производитель-оригинала», поставлено ближайшее — Caterpillar Inc. это изготовитель оригинала, а не неоригинала. хронология выхода: март 2022 — приостановка работы российских заводов («supply chain disruptions and sanctions»); апрель 2023 — остановка стройки в Санкт-Петербурге; ноябрь 2023 — Путин разрешил продажу ООО «ПСК-Новые решения»; 14 июня 2024 — активы переданы (завод в Тосно + лизинговая компания в Москве); июль 2024 — «Катерпиллар Тосно» переименован в ООО «Тосно», «Катерпиллар Файнэншл» — в ООО «Файнэншл»; апрель 2025 — выход формально зафиксирован; к декабрю 2025 г. проданы последние российские юрлица (~2,6 млрд руб.). Значит: гарантии завода, заводского сервиса и официальной поставки на РФ по R1700G не существует.', 'https://leave-russia.org/caterpillar', 'high', null),
  ('R1700G', 'ООО «ПСК-Новые решения» / Balchug Capital (Давид Амарян)', 'dealers', 'торговец', 'RU', 'Москва', 'покупатель российских активов Caterpillar: завод спецтехники в Тосно (Ленобласть) и лизинговая компания', '—', null, null, null, 'завод в Тосно; запчастями Cat не торгует', 'ПСК-Новые решения зарегистрировано в августе 2022 г., на 99 % принадлежит армянскому инвестфонду Balchug Capital. Сделка одобрена указом в ноябре 2023 г., закрыта 14.06.2024. Далее учредители менялись (июль 2024 — ООО «Инвестиционные решения», апрель 2025 — Мигаль А.П. и АО «Горизонт»). Для закупки запчастей R1700G бесполезно, но объясняет, почему у «наследника» нет ни каталога, ни доступа к SIS.', 'https://leave-russia.org/caterpillar', 'med', null),
  ('R1700G', 'Cat® Parts Store (parts.cat.com)', 'dealers', 'маркетплейс', 'US', '—', 'официальный интернет-магазин запчастей Caterpillar, ~1,5 млн позиций; заказ всегда идёт через выбранного дилера территории', 'Caterpillar, Cat Reman, Cat Classic', 'https://parts.cat.com/', null, null, 'склад — у дилера; забор со склада дилера или доставка дилером', 'механика важна для торгов: аккаунт в PCC привязывается к дилеру, поэтому покупка возможна только там, где у Cat есть дилер. Дилеры Борусан прямо описывают это на своих страницах («Parça Mağazası (Parts.Cat.Com) … заказ онлайн 24/7 без визита в точку продаж»). Для РФ дилера в системе нет, значит легальный PCC-заказ на российского получателя не собирается — только через юрлицо в KZ/KG/AM/TR/AE/CN. Из нашей среды сам parts.cat.com отдаёт 403 (гео/бот-фильтр), что косвенно подтверждает ограничение доступа.', 'https://www.borusancat.com/tr/part', 'med', null),
  ('R1700G', 'Cat® SIS 2.0 / SIS2GO (sis2.cat.com)', 'dealers', 'маркетплейс', 'US', '—', 'официальная система сервисной информации Cat: разузлование по модели и серийному номеру, схемы, процедуры, парт-номера', 'Caterpillar', 'https://sis2.cat.com/', null, null, '—', 'базовый доступ даёт аккаунт parts.cat.com (наборы, запчасти, безопасность), полный репозиторий — по платной годовой подписке Cat SIS Advanced, которую оформляет дилер. Интерфейс есть на русском. Практический вывод: без дилерского аккаунта разузловка R1700G по SIS для нас недоступна, и парт-номера приходится собирать по дилерским и вторичным каталогам.', 'https://www.petersoncat.com/parts/cat-service-information-system', 'med', null),
  ('R1700G', 'АО «ВЭД Агент»', 'dealers', 'торговец', 'RU', 'Новосибирск', 'таможенный брокер и импортёр полного цикла (Китай, Европа), консолидация грузов; офис в Шанхае', 'мультибренд', 'https://ved-agent.fis.ru/', null, '+7 383 328 43 84', 'сборные грузы из Китая и Европы; таможенное оформление, страхование', 'подтверждённый импортёр Caterpillar: в нашей таможенной выборке 2023 г. АО «ВЭД Агент» ввозило от CATERPILLAR INC (США) адаптер коронки ковша и фиксатор коронки — то есть GET-позиции, ровно тот класс деталей, что нужен по ковшу R1700G. Управляющий публично объясняет механику параллельного импорта.', 'https://ved-agent.fis.ru/', 'med', null),
  ('R1700G', 'ООО «СПК-Импорт» (spkamur.ru)', 'dealers', 'торговец', 'RU', 'Благовещенск', 'импорт и продажа запчастей для спецтехники из Китая, более 20 000 артикулов; Caterpillar в списке брендов', 'Caterpillar, SEM, XCMG, Komatsu, JCB, Shantui, Shehwa, FAW и 20+', 'https://spkamur.ru/', 'order@spkamur.ru', '8 800 707 65 94', 'склады Хэйхэ (КНР), Казань, Благовещенск; доставка по РФ 13 транспортными компаниями; гарантия до 6 месяцев по договору; работа с юрлицами — счёт, договор, НДС', 'подтверждённый импортёр Cat: в нашей таможне 4 строки Caterpillar и 4 строки по ПДМ на ООО «СПК-Импорт». Заявляет «оригинал и аналог по каждой позиции» — значит на запрос по R1700G надо жёстко требовать указания, что именно предлагается.', 'https://spkamur.ru/', 'high', null),
  ('R1700G', 'ООО «Хорошая Техника» (catparts.tech)', 'dealers', 'торговец', 'RU', 'Москва', 'поставка оригинальных запчастей Caterpillar для тех, у кого нет доступа к фирменному каналу', 'Caterpillar', 'https://catparts.tech/', 'lead@goodmash.ru', '+7 495 419 97 43', 'под заказ, международный прямой поставщик; наличие подтверждают по запросу', 'сама себя позиционирует как ответ на подделки и «аналоги сомнительного качества» — то есть работает в нише именно оригинала. Ни склада, ни сроков на сайте не заявлено: это посредник, цену и срок надо выбивать запросом.', 'https://catparts.tech/', 'med', null),
  ('R1700G', 'caterpillar-russia.com (поставки оборудования и запчастей Caterpillar)', 'dealers', 'торговец', 'RU', 'Москва', 'посредник по поставкам оборудования и оригинальных запчастей Caterpillar по РФ и СНГ', 'Caterpillar', 'https://caterpillar-russia.com/', 'sales@caterpillar-russia.com', '+7 495 125 10 49', 'заявлено: КП за 5 дней, доставка до 2 дней, гарантия 365 дней, фотоотчёт перед отгрузкой', 'осторожно: домен содержит товарный знак Caterpillar, юрлицо на сайте не раскрыто, статус к Caterpillar Inc. отношения не имеет. Заявленные «от 5 дней» по оригиналу для подземной техники выглядят нереалистично и требуют проверки конкретным парт-номером. Годится как один из адресов для контрольного запроса цены, не как основной канал.', 'https://caterpillar-russia.com/', 'low', null),
  ('R1700G', 'ProfiMiner (каталог поставщиков горной техники и запчастей)', 'dealers', 'маркетплейс', 'RU', 'Москва', 'отраслевой каталог: 44 компании в рубрике «поставщики запасных частей» для горной и карьерной техники, с локациями РФ, Беларуси, Китая и Венгрии', 'мультибренд', 'https://profiminer.ru/', 'info@profiminer.ru', '+7 901 184 85 33', '—', 'полезен как рабочий список адресов для рассылки ТКП по узлам R1700G и как независимая проверка статуса: карточка «Восточной Техники» там до сих пор описана как «официальный дилер компании Caterpillar в России с 1998 года, входит в группу Barloworld».', 'https://profiminer.ru/company/ccategory-part-dealer/', 'med', null),
  ('R1700G', 'ТОО «Hartex»', 'dealers', 'торговец', 'KZ', 'Алматы (и Усть-Каменогорск)', 'поставщик запчастей для спецтехники и дизельных двигателей, отдельный каталог Caterpillar (оригинал и аналоги)', 'Caterpillar и др.', 'https://hartex.kz/catalog/caterpillar/', 'sales@hartex.kz', '+7 771 116 44 44', 'более 30 000 запчастей; заявлена доставка по Казахстану, Киргизии и в Россию', 'прямо декларирует доставку в РФ — то есть готовая ЕАЭС-схема без таможенной границы на въезде. Адреса: Алматы, 8-й микрорайон 84а; Усть-Каменогорск, ул. Кожедуба 34/17 (Усть-Каменогорск — рядом с горными предприятиями ВКО).', 'https://hartex.kz/catalog/caterpillar/', 'high', null),
  ('R1700G', 'ТОО «Диггер-Про КЗ» (zemlekop.kz)', 'dealers', 'торговец', 'KZ', 'Астана', 'поставщик запчастей для спецтехники, каталог CAT; официальный представитель CARRARO и DANA SPICER в РК', 'Caterpillar, Carraro, Dana, ZF, Komatsu, Volvo, Perkins', 'https://zemlekop.kz/cat/', 'info@zemlekop.kz', '+7 7172 67 71 61', 'складской запас по востребованным фильтрам, уплотнениям и гидравлике; подбор по VIN машины или заводскому номеру детали; счёт, накладная, сертификат соответствия на каждую поставку', 'сильная сторона — трансмиссионная тема (Carraro/Dana): у R1700G шарнирно-сочленённая схема с мостами и гидромеханической передачей, так что это осмысленный адрес по мостам, дифференциалам и планетарным редукторам.', 'https://zemlekop.kz/cat/', 'high', null),
  ('R1700G', 'Q-Parts (quality-parts.kz / q-parts.kz)', 'dealers', 'торговец', 'KZ', 'Алматы', 'магазин запчастей для спецтехники Caterpillar (оригинал и качественные дубликаты)', 'Caterpillar, мультибренд', 'https://quality-parts.kz/g7223758-cat-caterpillar', 'info@q-parts.kz', '+7 727 317 11 11', 'склады Алматы и Астана; доставка по Казахстану, а также в Ташкент и Бишкек', 'по смыслу — розничный/мелкооптовый уровень. Годится для расходников и фильтров по R1700G, не для крупных узлов. По оригинальности требовать подтверждение: сами пишут про «качественные дубликаты».', 'https://quality-parts.kz/g7223758-cat-caterpillar', 'med', null),
  ('R1700G', 'ТОО «Rapid Parts Distribution» (RPD)', 'dealers', 'ремонт', 'KZ', 'Алматы', 'продажа оригинальных запчастей, сервис и ремонт газовых и дизельных силовых установок Caterpillar; официальный дилер DEIF в РК', 'Caterpillar, DEIF', 'https://rpd.kz/', 'info@rpd.kz', '+7 727 354 42 99', 'запчасти в наличии и под заказ по всем моделям (по заявлению на сайте)', 'узкая, но релевантная компетенция: R1700G построен на Cat C11/C15 ACERT, а RPD живёт ровно на двигателях Cat — капремонт, форсунки, ТНВД, ЭБУ. Для двигательной части машины это осмысленный исполнитель в ЕАЭС.', 'https://rpd.kz/', 'high', null),
  ('R1700G', 'Mechon International LLC FZ', 'dealers', 'торговец', 'AE', 'Дубай', 'поставщик оригинальных запчастей Caterpillar и тяжёлой техники; клиенты в 30+ странах', 'Caterpillar, Komatsu, Cummins, Volvo', 'https://mechoninternational.com/', 'sales@mechoninternational.com', '+971 4 572 9843', 'офис Al Qusais Plaza (Дамаск-стрит, оф. 703), регистрация Meydan; доставка в GCC, Африку, Южную Америку, Россию и Казахстан', 'прямо декларирует поставки в Россию и Казахстан и держит русскую версию сайта — то есть российский трафик для них целевой. Отдельно упоминает горные операции (Конго, Перу, Казахстан) и Cat-самосвалы/бульдозеры, значит горная номенклатура в профиле.', 'https://mechoninternational.com/brand/caterpillar-spare-parts-suppliers-dubai', 'high', null),
