  ('R1700G', 'Двигатель ранней машины — арр. ДВС 145-1730 = ENG AR 3176 (не C11)', '3176 (арр. 145-1730), снят с машины 8XZ00237 2000 г.в.', null, 'R1700G (8XZ)', 'https://parts.cat.com/en/catcorp/145-1730', 'med'),
  ('R1700G', 'Двигатель — прочие аналоги семейства по объёму', 'R1600H — тот же Cat C11, 11,1 л, bore 130 / stroke 140; R1600G и ранний R1700G — 3176/3176C', null, 'родня', 'https://s7d2.scene7.com/is/content/Caterpillar/CM20220926-d2996-7c866', 'high'),
