-- Досье машины R1700G для базы ЗИП. Сгенерировано zip/tools/r1700_sql.py
-- из zip/data/r1700.json (сборка 2026-09-12). Руками не править: правь досье и пересобери.
-- Идемпотентно: повторный прогон обновляет строки, а не двоит их.
-- Применение: Actions → «ZIP base — apply DB migrations», либо
--   psql "$SUPABASE_DB_URL" -v ON_ERROR_STOP=1 -f zip/supabase/seed_r1700.sql

begin;

on conflict (machine_key) do update set name = excluded.name, brand = excluded.brand, kind = excluded.kind, family = excluded.family, note = excluded.note, updated = excluded.updated;

on conflict (machine_key, form) do update set title = excluded.title, kind = excluded.kind, lang = excluded.lang, covers = excluded.covers, media = excluded.media, where_get = excluded.where_get, url = excluded.url, price = excluded.price, confidence = excluded.confidence, verdict = excluded.verdict;

on conflict (machine_key, pn_norm) do update set pn = excluded.pn, name_ru = excluded.name_ru, name_en = excluded.name_en, node = excluded.node, applic = excluded.applic, qty = excluded.qty, interval_h = excluded.interval_h, price_usd = excluded.price_usd, price_eur_min = excluded.price_eur_min, price_eur_max = excluded.price_eur_max, kv = excluded.kv, position_id = excluded.position_id, bitrix_status = excluded.bitrix_status, confidence = excluded.confidence, verdict = excluded.verdict, sources = excluded.sources, note = excluded.note;

on conflict (machine_key, pn_norm) do update set pn = excluded.pn, name_ru = excluded.name_ru, name_en = excluded.name_en, node = excluded.node, applic = excluded.applic, qty = excluded.qty, interval_h = excluded.interval_h, price_usd = excluded.price_usd, price_eur_min = excluded.price_eur_min, price_eur_max = excluded.price_eur_max, kv = excluded.kv, position_id = excluded.position_id, bitrix_status = excluded.bitrix_status, confidence = excluded.confidence, verdict = excluded.verdict, sources = excluded.sources, note = excluded.note;

on conflict (machine_key, pn_norm, brand, alt_pn_norm) do update set alt_pn = excluded.alt_pn, kind = excluded.kind, note = excluded.note;

on conflict (machine_key, pn_norm, brand, alt_pn_norm) do update set alt_pn = excluded.alt_pn, kind = excluded.kind, note = excluded.note;

on conflict (machine_key, pn_norm, brand, alt_pn_norm) do update set alt_pn = excluded.alt_pn, kind = excluded.kind, note = excluded.note;

on conflict (machine_key, org, lane) do update set kind = excluded.kind, country = excluded.country, city = excluded.city, role = excluded.role, brands = excluded.brands, site = excluded.site, email = excluded.email, phone = excluded.phone, stock = excluded.stock, note = excluded.note, source = excluded.source, confidence = excluded.confidence, verdict = excluded.verdict;

delete from mach_prices  where machine_key = 'R1700G';
-- mach_prices: нет строк

delete from mach_specs   where machine_key = 'R1700G';
;

delete from mach_tenders where machine_key = 'R1700G';
-- mach_tenders: нет строк

delete from mach_customs where machine_key = 'R1700G';
;


commit;

